def check_condition(n):
    """
    Checks if k^2 - 1 is a multiple of n for all k coprime to n.
    """
    if n < 2:
        return False # Constraint n >= 2

    for k in range(1, n):
        import math
        if math.gcd(k, n) == 1:
            if (k*k - 1) % n != 0:
                return False, k
    return True, None

test_values = [2, 3, 4, 5, 6, 7, 8, 9, 10, 12]
results = {}
for n in test_values:
    holds, failing_k = check_condition(n)
    results[n] = (holds, failing_k)

print("Results for small n:")
for n, (holds, failing_k) in results.items():
    print(f"n={n}: {'Holds' if holds else 'Fails'} (Failing k: {failing_k} if not holds else 'N/A')")

